plotatab2 <- function(filey,sheet,head=T){
  if(head){
    dat = read_xlsx(filey,sheet)
    kable(dat,"simple") 
  }else{
    dat = read_xlsx(filey,sheet,col_names=F)
    kable(dat,"simple",col.names=rep("",ncol(dat))) 
  }
}



